    skRectangle(s2, "rect1", { "firstCorner" : vector(-5, -5) * millimeter, "secondCorner" : vector(5, 5) * millimeter });
    skSolve(s2);
    const g0 = newSketchOnPlane(context, id + "g0", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(g0, "a1", { "start" : vector(10, 0) * millimeter, "mid" : vector(13, 10) * millimeter, "end" : vector(5, 20) * millimeter });
